function dayDiff(fromIso, toIso) {
  const a = Date.parse(String(fromIso) + 'T00:00:00Z');
  const b = Date.parse(String(toIso) + 'T00:00:00Z');
  if (isNaN(a) || isNaN(b)) return null;
  return Math.round((b - a) / 86400000);
}
function shiftIso(iso, days) {
  const t = Date.parse(String(iso) + 'T00:00:00Z');
  if (isNaN(t)) return '';
  return new Date(t - days * 86400000).toISOString().slice(0, 10);
}
function truthy(v) {
  return v === true || v === 'true' || v === 1 || v === '1';
}

const today = new Date().toISOString().slice(0, 10);

const existing = {};
for (const it of $('Load Existing Tasks').all()) {
  const r = it.json || {};
  if (!r.task_key) continue;
  existing[String(r.task_key).trim()] = r;
}

const template = $('Load Onboarding Checklist').all()
  .map(function (i) { return i.json || {}; })
  .filter(function (t) { return t.task_code; });

const out = [];

for (const it of $('Load New Hires').all()) {
  const h = it.json || {};
  const hireId = String(h.hire_id || '').trim().toUpperCase();
  const status = String(h.status || 'pending').trim().toLowerCase();
  const startDate = String(h.start_date || '').trim();
  const role = String(h.role || '').trim();
  const dept = String(h.department || '').trim();
  const empType = String(h.employment_type || '').trim();

  if (!hireId) continue;
  if (status === 'cancelled') continue;
  if (dayDiff(startDate, today) === null) continue;

  const wanted = template.filter(function (t) {
    const a = String(t.applies_to || 'ALL').trim();
    if (a === 'ALL') return true;
    if (a.indexOf('ROLE:') === 0) return a.slice(5).trim().toLowerCase() === role.toLowerCase();
    if (a.indexOf('DEPT:') === 0) return a.slice(5).trim().toLowerCase() === dept.toLowerCase();
    if (a.indexOf('TYPE:') === 0) return a.slice(5).trim().toLowerCase() === empType.toLowerCase();
    return false;
  });

  for (const t of wanted) {
    const taskCode = String(t.task_code).trim().toUpperCase();
    const taskKey = hireId + '|' + taskCode;
    const prev = existing[taskKey] || null;
    const leadDays = Number(t.lead_days) || 0;
    const dueDate = shiftIso(startDate, leadDays);

    out.push({
      json: {
        task_key: taskKey,
        hire_id: hireId,
        hire_name: String(h.full_name || ''),
        hire_role: role,
        hire_department: dept,
        employment_type: empType,
        manager: String(h.manager || ''),
        manager_email: String(h.manager_email || ''),
        start_date: startDate,
        days_to_start: dayDiff(today, startDate),
        task_code: taskCode,
        task_name: String(t.task_name || ''),
        owner_team: String(t.owner_team || 'Unassigned'),
        owner_email: String(t.owner_email || ''),
        due_date: dueDate,
        days_to_due: dayDiff(today, dueDate),
        mandatory: truthy(t.mandatory),
        blocks_day_one: truthy(t.blocks_day_one),
        status: prev ? String(prev.status || 'open').trim().toLowerCase() : 'open',
        completed_on: prev ? String(prev.completed_on || '') : '',
        completed_by: prev ? String(prev.completed_by || '') : '',
        blocked_reason: prev ? String(prev.blocked_reason || '') : '',
        last_chased_on: prev ? String(prev.last_chased_on || '') : '',
        created_on: prev ? String(prev.created_on || today) : today,
        is_new: prev ? false : true,
        assessed_on: today,
        execution_id: String($execution.id || 'manual')
      }
    });
  }
}

return out;

const AT_RISK_WINDOW_DAYS = 7;

const today = new Date().toISOString().slice(0, 10);

const byHire = {};
for (const it of $('Expand the Checklist per Hire').all()) {
  const r = it.json || {};
  const k = r.hire_id;
  if (!byHire[k]) byHire[k] = [];
  byHire[k].push(r);
}

const out = [];

for (const hireId of Object.keys(byHire)) {
  const tasks = byHire[hireId];
  const any = tasks[0];

  const done = tasks.filter(function (t) { return t.status === 'done'; });
  const blocked = tasks.filter(function (t) { return t.status === 'blocked'; });
  const open = tasks.filter(function (t) { return t.status !== 'done' && t.status !== 'blocked'; });
  const overdue = open.filter(function (t) { return Number(t.days_to_due) < 0; });
  const mandatoryOpen = open.concat(blocked).filter(function (t) { return t.mandatory; });
  const dayOneGaps = open.concat(blocked).filter(function (t) { return t.blocks_day_one; });

  const daysToStart = Number(any.days_to_start);
  const readiness = tasks.length ? Math.round((done.length / tasks.length) * 100) : 0;

  let outcome = '';
  let headline = '';

  if (blocked.length) {
    outcome = 'blocked';
    headline = blocked.length + ' task(s) blocked and someone has to unblock them: ' +
      blocked.map(function (t) { return t.task_name + ' (' + t.owner_team + ') - ' + (t.blocked_reason || 'no reason given'); }).join('; ');
  } else if (!mandatoryOpen.length) {
    outcome = 'ready';
    headline = 'Every mandatory task is done. ' + any.hire_name + ' can start on ' + any.start_date + ' with an account, a desk and a laptop.';
  } else if (dayOneGaps.length && daysToStart <= AT_RISK_WINDOW_DAYS) {
    outcome = 'at_risk';
    headline = daysToStart < 0
      ? (any.hire_name + ' STARTED ' + (-daysToStart) + ' day(s) ago and still has ' + dayOneGaps.length + ' day-one task(s) outstanding.')
      : (any.hire_name + ' starts in ' + daysToStart + ' day(s) with ' + dayOneGaps.length + ' day-one task(s) still open: ' +
         dayOneGaps.map(function (t) { return t.task_name + ' (' + t.owner_team + ')'; }).join(', ') + '.');
  } else {
    outcome = 'on_track';
    headline = readiness + '% complete, ' + daysToStart + ' day(s) to go. Nothing needs chasing yet.';
  }

  out.push({
    json: {
      hire_id: hireId,
      hire_name: any.hire_name,
      hire_role: any.hire_role,
      hire_department: any.hire_department,
      employment_type: any.employment_type,
      manager: any.manager,
      manager_email: any.manager_email,
      start_date: any.start_date,
      days_to_start: daysToStart,
      outcome: outcome,
      headline: headline,
      readiness_pct: readiness,
      task_total: tasks.length,
      task_done: done.length,
      task_open: open.length,
      task_blocked: blocked.length,
      task_overdue: overdue.length,
      day_one_gaps: dayOneGaps.length,
      newly_created: tasks.filter(function (t) { return t.is_new; }).length,
      outstanding: open.concat(blocked).map(function (t) {
        return {
          task: t.task_name,
          code: t.task_code,
          owner: t.owner_team,
          due: t.due_date,
          days_to_due: t.days_to_due,
          status: t.status,
          blocks_day_one: t.blocks_day_one,
          reason: t.blocked_reason
        };
      }).sort(function (a, b) { return a.days_to_due - b.days_to_due; }),
      assessed_on: today,
      execution_id: String($execution.id || 'manual')
    }
  });
}

out.sort(function (a, b) { return a.json.days_to_start - b.json.days_to_start; });
return out;

