const CHASE_GAP_DAYS = 2;

const today = new Date().toISOString().slice(0, 10);

function dayDiff(fromIso, toIso) {
  const a = Date.parse(String(fromIso) + 'T00:00:00Z');
  const b = Date.parse(String(toIso) + 'T00:00:00Z');
  if (isNaN(a) || isNaN(b)) return null;
  return Math.round((b - a) / 86400000);
}

const byOwner = {};
for (const it of $('Expand the Checklist per Hire').all()) {
  const t = it.json || {};
  if (t.status === 'done') continue;
  const k = String(t.owner_team || 'Unassigned');
  if (!byOwner[k]) byOwner[k] = [];
  byOwner[k].push(t);
}

const out = [];

for (const team of Object.keys(byOwner)) {
  const tasks = byOwner[team];
  const chased = tasks.filter(function (t) {
    const since = t.last_chased_on ? dayDiff(t.last_chased_on, today) : null;
    return since !== null && since < CHASE_GAP_DAYS;
  });
  const dueNow = tasks.filter(function (t) { return Number(t.days_to_due) <= 3; });
  const overdue = tasks.filter(function (t) { return Number(t.days_to_due) < 0; });
  const blockers = tasks.filter(function (t) { return t.blocks_day_one; });

  const suppressed = chased.length === tasks.length && tasks.length > 0;

  out.push({
    json: {
      owner_team: team,
      owner_email: String(tasks[0].owner_email || ''),
      task_count: tasks.length,
      overdue_count: overdue.length,
      due_soon_count: dueNow.length,
      day_one_blocker_count: blockers.length,
      hires_touched: Array.from(new Set(tasks.map(function (t) { return t.hire_name; }))).length,
      urgency: overdue.length ? 'overdue' : (dueNow.length ? 'due_soon' : 'ahead'),
      send_digest: !suppressed && (overdue.length > 0 || dueNow.length > 0),
      suppressed_reason: suppressed ? ('Every outstanding task for ' + team + ' was already chased within the last ' + CHASE_GAP_DAYS + ' day(s).') : '',
      lines: tasks.map(function (t) {
        return {
          hire: t.hire_name,
          starts: t.start_date,
          task: t.task_name,
          due: t.due_date,
          days_to_due: t.days_to_due,
          status: t.status,
          blocks_day_one: t.blocks_day_one,
          reason: t.blocked_reason
        };
      }).sort(function (a, b) { return a.days_to_due - b.days_to_due; }),
      assessed_on: today,
      execution_id: String($execution.id || 'manual')
    }
  });
}

out.sort(function (a, b) { return b.json.overdue_count - a.json.overdue_count; });
return out;

